// ============================================================================
// Config & Safety Gate
// Reads ONLY environment variables (never hardcoded secrets) and resolves a
// fail-safe runtime configuration. Secrets are never copied into item data:
// only presence booleans (hasHubspotToken, hasGitToken, ...) leave this node.
//
// Safety semantics:
//   * "Safe-ON" flags (SANDBOX_MODE, DRY_RUN) switch OFF only on an explicit
//     false/0/no/off. Typos, blanks and unknown values keep them ON.
//   * "Safe-OFF" flags (GIT_COMMITS_ENABLED, NOTIFICATIONS_ENABLED, ...) switch
//     ON only on an explicit true/1/yes/on.
//   * If n8n blocks $env access, every flag falls back to its safe default.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;

function readEnv(key) {
  try {
    const v = $env[key];
    if (v === undefined || v === null) return '';
    return String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (key, dflt = '') => readEnv(key) || dflt;
const safeOn = (key) => !FALSY.includes(readEnv(key).toLowerCase());
const safeOff = (key) => TRUTHY.includes(readEnv(key).toLowerCase());
const list = (key, dflt) =>
  (readEnv(key) || dflt)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
const int = (key, dflt, min, max) => {
  const n = parseInt(readEnv(key), 10);
  if (Number.isNaN(n)) return dflt;
  return Math.min(max, Math.max(min, n));
};

const SYNTHETIC_PORTAL_ID = '99000001';
const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const gitCommitsEnabled = safeOff('GIT_COMMITS_ENABLED');
const notificationsEnabled = safeOff('NOTIFICATIONS_ENABLED');

const hasHubspotToken = readEnv('HUBSPOT_ACCESS_TOKEN') !== '';
const hasGitToken = readEnv('GITHUB_PAT') !== '';
const hasWebhook = readEnv('SLACK_WEBHOOK_URL') !== '';

// ---- Portal identity -------------------------------------------------------
// Sandbox runs always use the synthetic portal ID so that mock data can never
// be filed under a real portal folder in the backup repository.
const configuredPortalId = str('HUBSPOT_PORTAL_ID');
const portalId = sandboxMode ? SYNTHETIC_PORTAL_ID : configuredPortalId;

if (!sandboxMode) {
  const problems = [];
  if (!hasHubspotToken) problems.push('HUBSPOT_ACCESS_TOKEN is not set');
  if (!/^\d{1,12}$/.test(configuredPortalId)) problems.push('HUBSPOT_PORTAL_ID must be a numeric HubSpot portal (Hub) ID');
  if (problems.length) {
    throw new Error(
      'Live mode (SANDBOX_MODE=false) refused: ' + problems.join('; ') +
      '. Set the missing variables or re-enable SANDBOX_MODE=true.'
    );
  }
}

// ---- Export scope ----------------------------------------------------------
const objectTypes = list('EXPORT_OBJECT_TYPES', 'contacts,companies,deals,tickets')
  .filter((t) => /^[a-z0-9_\-]+$/i.test(t));
const pipelineObjectTypes = list('EXPORT_PIPELINE_OBJECT_TYPES', 'deals,tickets')
  .filter((t) => /^[a-z0-9_\-]+$/i.test(t));
const workflowsApi = str('HUBSPOT_WORKFLOWS_API', 'v4').toLowerCase() === 'v3' ? 'v3' : 'v4';

const scope = {
  customObjects: safeOn('EXPORT_CUSTOM_OBJECTS'),
  properties: safeOn('EXPORT_PROPERTIES'),
  propertyGroups: safeOn('EXPORT_PROPERTY_GROUPS'),
  pipelines: safeOn('EXPORT_PIPELINES'),
  workflows: safeOn('EXPORT_WORKFLOWS'),
  includeHubspotDefinedProperties: safeOff('EXPORT_HUBSPOT_DEFINED_PROPERTIES'),
  objectTypes,
  pipelineObjectTypes,
  workflowsApi,
};

// ---- Normalization options -------------------------------------------------
const normalization = {
  stripVolatileTimestamps: safeOn('STRIP_VOLATILE_TIMESTAMPS'),
  redactUserIds: safeOn('REDACT_USER_IDS'),
  verifyPortalId: safeOn('VERIFY_PORTAL_ID'),
};

// ---- Git target ------------------------------------------------------------
const repo = str('GITHUB_REPOSITORY');
const repoValid = /^[A-Za-z0-9_.\-]+\/[A-Za-z0-9_.\-]+$/.test(repo);
const branch = str('GIT_BRANCH', 'hubspot-config-snapshots');
const branchValid = /^[A-Za-z0-9._\/\-]+$/.test(branch) && !branch.includes('..');
const protectedBranches = list('GIT_PROTECTED_BRANCHES', 'main,master,production');
const allowProtectedBranch = safeOff('GIT_ALLOW_PROTECTED_BRANCH');
const apiBase = str('GITHUB_API_BASE_URL', 'https://api.github.com').replace(/\/+$/, '');
const snapshotRoot = str('GIT_SNAPSHOT_ROOT', 'snapshots').replace(/^\/+|\/+$/g, '') + '/portal-' + portalId;
const webUrl = str('GIT_REPO_URL').replace(/\.git$/, '').replace(/\/+$/, '');

// Static commit-gate reasons (dynamic ones such as health and "no changes"
// are added later by the Versioned Diff Builder).
const commitBlockers = [];
if (sandboxMode) commitBlockers.push('SANDBOX_MODE=true (synthetic fixture run)');
if (dryRun) commitBlockers.push('DRY_RUN=true');
if (!gitCommitsEnabled) commitBlockers.push('GIT_COMMITS_ENABLED is not true');
if (!hasGitToken) commitBlockers.push('GITHUB_PAT is not set');
if (!repoValid) commitBlockers.push('GITHUB_REPOSITORY is missing or not in owner/repo form');
if (!branchValid) commitBlockers.push('GIT_BRANCH contains unsupported characters');
if (protectedBranches.includes(branch) && !allowProtectedBranch) {
  commitBlockers.push(`GIT_BRANCH "${branch}" is protected (set GIT_ALLOW_PROTECTED_BRANCH=true to override)`);
}
if (envBlocked) commitBlockers.push('n8n blocked $env access (N8N_BLOCK_ENV_ACCESS_IN_NODE)');

const remoteReadAllowed =
  !sandboxMode && hasGitToken && repoValid && branchValid && safeOn('GIT_REMOTE_DIFF_ENABLED');

const notifyAllowed = notificationsEnabled && hasWebhook && !envBlocked;

const capturedAt = (() => {
  const override = str('SNAPSHOT_TIMESTAMP_OVERRIDE');
  if (override && !Number.isNaN(Date.parse(override))) return new Date(override).toISOString();
  return new Date().toISOString();
})();

const config = {
  runId: 'snap-' + capturedAt.replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 8),
  capturedAt,
  snapshotVersion: 'v' + capturedAt.replace(/[-:]/g, '').replace(/\.\d+Z$/, 'Z'),
  envBlocked,
  sandboxMode,
  dryRun,
  portalId,
  hubspot: {
    apiBase: str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, ''),
    hasToken: hasHubspotToken,
    workflowsUrl: '',
  },
  scope,
  normalization,
  git: {
    commitsEnabled: gitCommitsEnabled,
    hasToken: hasGitToken,
    repo: repoValid ? repo : '',
    branch,
    apiBase,
    apiRepoBase: repoValid ? `${apiBase}/repos/${repo}` : '',
    snapshotRoot,
    webUrl,
    pruneRemovedFiles: safeOff('GIT_PRUNE_REMOVED_FILES'),
    commitOnDegraded: safeOff('GIT_COMMIT_ON_DEGRADED'),
    commitAuthorName: str('GIT_COMMIT_AUTHOR_NAME', 'HubSpot Config Snapshot Bot'),
    commitAuthorEmail: str('GIT_COMMIT_AUTHOR_EMAIL', 'snapshot-bot@example.invalid'),
    remoteReadAllowed,
    staticCommitBlockers: commitBlockers,
  },
  notify: {
    enabled: notificationsEnabled,
    hasWebhook,
    allowed: notifyAllowed,
    channelLabel: str('NOTIFY_CHANNEL_LABEL', '#revops-alerts'),
  },
  limits: {
    // Must match the pagination "Max Pages" (50) on the HubSpot Workflows Export node.
    maxWorkflowPages: 50,
    maxRecordNamesInCommit: int('COMMIT_MESSAGE_MAX_RECORD_NAMES', 15, 1, 200),
  },
};

config.hubspot.workflowsUrl =
  workflowsApi === 'v3'
    ? `${config.hubspot.apiBase}/automation/v3/workflows`
    : `${config.hubspot.apiBase}/automation/v4/flows?limit=100`;

const safetyDecisions = [
  `Mode: ${sandboxMode ? 'SANDBOX (synthetic fixture, zero network calls)' : 'LIVE (read-only HubSpot GET requests)'}`,
  `Dry run: ${dryRun}`,
  `Git commits: ${commitBlockers.length === 0 ? 'ARMED (subject to health and change checks)' : 'BLOCKED'}`,
  `Remote diff read: ${remoteReadAllowed}`,
  `Notifications: ${notifyAllowed ? 'ENABLED' : 'DISABLED'}`,
];

return [{ json: { config, safetyDecisions } }];

// ============================================================================
// Build HubSpot Export Requests  (LIVE path only)
// Emits one item per read-only GET request. The HTTP node that follows sends
// them with rate-limit friendly batching; "Collect & Verify API Responses"
// re-pairs responses to requests by index.
// Workflows are fetched separately (paginated) by "HubSpot Workflows Export".
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const base = config.hubspot.apiBase;
const s = config.scope;
const reqs = [];
const add = (key, path, required = true) => reqs.push({ json: { key, url: `${base}${path}`, method: 'GET', required } });

if (config.normalization.verifyPortalId) add('accountInfo', '/account-info/v3/details', false);
if (s.customObjects) add('customObjectSchemas', '/crm/v3/schemas?archived=false');
for (const t of s.objectTypes) {
  if (s.properties) add(`properties:${t}`, `/crm/v3/properties/${encodeURIComponent(t)}?archived=false`);
  if (s.propertyGroups) add(`propertyGroups:${t}`, `/crm/v3/properties/${encodeURIComponent(t)}/groups?archived=false`);
}
if (s.pipelines) {
  for (const t of s.pipelineObjectTypes) add(`pipelines:${t}`, `/crm/v3/pipelines/${encodeURIComponent(t)}`);
}

if (reqs.length === 0) {
  throw new Error('Export scope is empty: enable at least one EXPORT_* flag or keep the defaults.');
}
return reqs;

// ============================================================================
// Collect & Verify API Responses  (LIVE path only)
// Pairs each HTTP response with its originating request (same index order),
// records per-endpoint failures instead of aborting, and enforces the portal
// guard: a token that belongs to a different portal than HUBSPOT_PORTAL_ID
// stops the run before anything can be written to Git.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const requests = $('Build HubSpot Export Requests').all();
const responses = $input.all();

const raw = {
  portalId: config.portalId,
  accountInfo: null,
  customObjectSchemas: config.scope.customObjects ? [] : null,
  properties: config.scope.properties ? {} : null,
  propertyGroups: config.scope.propertyGroups ? {} : null,
  pipelines: config.scope.pipelines ? {} : null,
  workflows: null,
  workflowsApi: config.scope.workflowsApi,
};
const endpointErrors = [];
const warnings = [];

const errMessage = (body) => {
  const e = body && body.error;
  if (!e) return null;
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e).slice(0, 300);
};

if (responses.length !== requests.length) {
  warnings.push(`Response count (${responses.length}) differs from request count (${requests.length}); pairing by index may be unreliable.`);
}

requests.forEach((req, i) => {
  const { key, required } = req.json;
  const body = responses[i] ? responses[i].json : undefined;
  const failure = body === undefined ? 'No response item' : errMessage(body);
  if (failure) {
    if (required) endpointErrors.push({ key, message: String(failure).slice(0, 300) });
    else warnings.push(`Optional endpoint ${key} failed: ${String(failure).slice(0, 200)}`);
    return;
  }
  const [kind, objectType] = key.split(':');
  const results = Array.isArray(body.results) ? body.results : null;
  switch (kind) {
    case 'accountInfo':
      raw.accountInfo = body;
      break;
    case 'customObjectSchemas':
      raw.customObjectSchemas = results || [];
      break;
    case 'properties':
      raw.properties[objectType] = results || [];
      break;
    case 'propertyGroups':
      raw.propertyGroups[objectType] = results || [];
      break;
    case 'pipelines':
      raw.pipelines[objectType] = results || [];
      break;
    default:
      warnings.push(`Unrecognised request key ${key}`);
  }
  if (kind !== 'accountInfo' && !results) warnings.push(`Endpoint ${key} returned no "results" array`);
});

// ---- Portal guard ----------------------------------------------------------
if (config.normalization.verifyPortalId) {
  if (raw.accountInfo && raw.accountInfo.portalId !== undefined) {
    const actual = String(raw.accountInfo.portalId);
    if (actual !== String(config.portalId)) {
      throw new Error(
        `Portal guard: the HubSpot token belongs to portal ${actual} but HUBSPOT_PORTAL_ID is ${config.portalId}. ` +
        'Refusing to continue so one portal is never filed under another portal\'s backup folder.'
      );
    }
  } else {
    warnings.push('Portal guard could not read /account-info/v3/details; portal ID was not independently verified.');
  }
}

return [{ json: { source: 'hubspot-api', raw, endpointErrors, warnings } }];

// ============================================================================
// Assemble Raw Snapshot  (LIVE path only)
// Merges paginated workflow pages (v4 "results" or v3 "workflows") into the
// CRM metadata collected upstream. Runs whether or not workflows are in scope.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const crm = $('Collect & Verify API Responses').first().json;
const raw = JSON.parse(JSON.stringify(crm.raw));
const endpointErrors = [...crm.endpointErrors];
const warnings = [...crm.warnings];

if (config.scope.workflows) {
  const pages = $input.all().map((i) => i.json);
  const failed = pages.find((p) => p && p.error);
  if (failed) {
    const e = failed.error;
    endpointErrors.push({
      key: 'workflows',
      message: String(typeof e === 'string' ? e : e.message || JSON.stringify(e)).slice(0, 300),
      hint: 'Check the private app has the "automation" scope and the portal tier exposes the Workflows API.',
    });
  } else {
    const all = [];
    for (const p of pages) {
      if (Array.isArray(p.results)) all.push(...p.results);
      else if (Array.isArray(p.workflows)) all.push(...p.workflows);
    }
    raw.workflows = all;
    if (pages.length >= config.limits.maxWorkflowPages) {
      warnings.push(`Workflow pagination stopped at the node's ${config.limits.maxWorkflowPages}-page cap; the list may be incomplete.`);
    }
  }
}

return [{ json: { source: crm.source, raw, endpointErrors, warnings } }];

// ============================================================================
// Normalization & Checksum Auditor
// 1. Scrubs volatile timestamps and user IDs (configurable).
// 2. Sorts every object key and every record array deterministically, so the
//    same portal configuration always serialises to the same bytes.
// 3. Splits the snapshot into one JSON file per object type / concern.
// 4. Computes SHA-256 per file, per record (short hash) and for the bundle.
// 5. Re-parses every file and re-hashes it (integrity self-check).
// 6. Runs RevOps sanity checks (empty picklists, duplicate names, pipelines
//    without a closed stage, out-of-range probabilities...).
// Uses Node's crypto module when n8n allows it (NODE_FUNCTION_ALLOW_BUILTIN=crypto)
// and otherwise falls back to the bundled pure-JS SHA-256 below. Both produce
// identical digests (verified by scripts/simulate-sandbox-run.js).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const input = $input.first().json;
const raw = input.raw || {};
const opts = config.normalization;
const scope = config.scope;

// ---------------------------------------------------------------- utf-8 / hash
function utf8Bytes(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      const d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256Fallback(str) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bytes = utf8Bytes(str);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const W = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] = ((bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
}

let hashEngine = 'pure-js';
let nodeCrypto = null;
try {
  nodeCrypto = require('crypto');
  if (nodeCrypto && typeof nodeCrypto.createHash === 'function') hashEngine = 'node:crypto';
  else nodeCrypto = null;
} catch (e) {
  nodeCrypto = null;
}
const sha256 = (s) => (nodeCrypto ? nodeCrypto.createHash('sha256').update(s, 'utf8').digest('hex') : sha256Fallback(s));

// ------------------------------------------------------------ canonical JSON
function canonical(v) {
  if (Array.isArray(v)) return v.map(canonical);
  if (v && typeof v === 'object') {
    const out = {};
    for (const k of Object.keys(v).sort()) {
      if (v[k] === undefined) continue;
      out[k] = canonical(v[k]);
    }
    return out;
  }
  return v;
}
const serialize = (v) => JSON.stringify(canonical(v), null, 2) + '\n';

// ------------------------------------------------------------------- scrub
const USER_ID_KEYS = new Set(['createdUserId', 'updatedUserId', 'createdByUserId', 'updatedByUserId', 'userId']);
const VOLATILE_KEYS = new Set(['updatedAt']);
function scrub(v, { stripTimestamps }) {
  if (Array.isArray(v)) return v.map((x) => scrub(x, { stripTimestamps }));
  if (v && typeof v === 'object') {
    const out = {};
    for (const [k, val] of Object.entries(v)) {
      if (opts.redactUserIds && USER_ID_KEYS.has(k)) continue;
      if (stripTimestamps && VOLATILE_KEYS.has(k)) continue;
      out[k] = scrub(val, { stripTimestamps });
    }
    return out;
  }
  return v;
}
const scrubCrm = (v) => scrub(v, { stripTimestamps: opts.stripVolatileTimestamps });

// ------------------------------------------------------------------- sort
const cmpStr = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
const cmpIdLike = (a, b) => {
  const sa = String(a), sb = String(b);
  if (/^\d+$/.test(sa) && /^\d+$/.test(sb) && sa.length !== sb.length) return sa.length - sb.length;
  return cmpStr(sa, sb);
};
const byName = (a, b) => cmpStr(String(a.name || ''), String(b.name || ''));
const byOrderThenId = (a, b) => (Number(a.displayOrder ?? 0) - Number(b.displayOrder ?? 0)) || cmpIdLike(a.id, b.id);

function normProperty(p) {
  const q = scrubCrm(p);
  if (Array.isArray(q.options)) {
    q.options = [...q.options].sort((a, b) => cmpStr(String(a.value), String(b.value)));
  }
  return q;
}
function normPipeline(p) {
  const q = scrubCrm(p);
  if (Array.isArray(q.stages)) q.stages = [...q.stages].sort(byOrderThenId);
  return q;
}
const WORKFLOW_ALLOWLIST = ['id', 'name', 'description', 'flowType', 'type', 'objectTypeId', 'isEnabled', 'enabled', 'revisionId', 'createdAt', 'insertedAt', 'updatedAt'];
function normWorkflow(w) {
  // Allowlist only: action graphs, enrollment criteria and email bodies are
  // deliberately NOT exported, so no PII or message content can leak into Git.
  const pick = {};
  for (const k of WORKFLOW_ALLOWLIST) if (w[k] !== undefined && w[k] !== null) pick[k] = w[k];
  return scrub({
    id: String(pick.id),
    name: pick.name ?? null,
    description: pick.description ?? null,
    kind: pick.flowType ?? pick.type ?? null,
    objectTypeId: pick.objectTypeId ?? (raw.workflowsApi === 'v3' ? '0-1' : null),
    enabled: pick.isEnabled ?? pick.enabled ?? null,
    revisionId: pick.revisionId !== undefined ? String(pick.revisionId) : null,
    createdAt: pick.createdAt ?? (typeof pick.insertedAt === 'number' ? new Date(pick.insertedAt).toISOString() : pick.insertedAt ?? null),
    updatedAt: typeof pick.updatedAt === 'number' ? new Date(pick.updatedAt).toISOString() : pick.updatedAt ?? null,
    sourceApi: raw.workflowsApi || 'v4',
  }, { stripTimestamps: false });
}

// ------------------------------------------------------------ file builder
const files = [];
const warnings = [...(input.warnings || [])];
const errors = [];
const counts = { customObjects: 0, properties: 0, propertyGroups: 0, pipelines: 0, pipelineStages: 0, workflows: 0 };
const safeSeg = (s) => String(s).replace(/[^A-Za-z0-9_\-.]/g, '_');

function addFile(path, kind, objectType, records, keyFn) {
  const content = serialize(records);
  const recordHashes = {};
  for (const r of records) {
    const k = String(keyFn(r));
    if (recordHashes[k]) warnings.push(`${path}: duplicate record key "${k}"`);
    recordHashes[k] = sha256(serialize(r)).slice(0, 16);
  }
  files.push({
    path,
    kind,
    objectType,
    records: records.length,
    bytes: utf8Bytes(content).length,
    sha256: sha256(content),
    recordHashes,
    content,
  });
}

const keepProperty = (p) => scope.includeHubspotDefinedProperties || p.hubspotDefined !== true;

// Custom object schemas (+ their properties as a separate file each).
if (Array.isArray(raw.customObjectSchemas)) {
  const schemas = [...raw.customObjectSchemas].sort((a, b) => cmpStr(String(a.objectTypeId || a.name), String(b.objectTypeId || b.name)));
  const schemaRecords = [];
  for (const s of schemas) {
    const { properties = [], ...rest } = s;
    const rec = scrubCrm(rest);
    if (Array.isArray(rec.associations)) rec.associations = [...rec.associations].sort((a, b) => cmpIdLike(a.id, b.id));
    for (const k of ['requiredProperties', 'searchableProperties', 'secondaryDisplayProperties']) {
      if (Array.isArray(rec[k])) rec[k] = [...rec[k]].sort(cmpStr);
    }
    rec.propertyCount = properties.filter(keepProperty).length;
    schemaRecords.push(rec);
    const props = properties.filter(keepProperty).map(normProperty).sort(byName);
    addFile(`custom-objects/${safeSeg(s.name || s.objectTypeId)}/properties.json`, 'customObjectProperties', s.objectTypeId, props, (r) => r.name);
    counts.properties += props.length;
    if (!rec.primaryDisplayProperty) warnings.push(`Custom object ${s.name}: no primaryDisplayProperty set`);
  }
  addFile('custom-objects/schemas.json', 'customObjectSchemas', null, schemaRecords, (r) => r.objectTypeId || r.name);
  counts.customObjects = schemaRecords.length;
}

// CRM properties per object type.
if (raw.properties) {
  for (const t of Object.keys(raw.properties).sort()) {
    const props = (raw.properties[t] || []).filter(keepProperty).map(normProperty).sort(byName);
    for (const p of props) {
      if (!p.label) warnings.push(`properties/${t}: "${p.name}" has an empty label`);
      if (p.type === 'enumeration' && (!Array.isArray(p.options) || p.options.length === 0) && !p.externalOptions) {
        warnings.push(`properties/${t}: enumeration "${p.name}" has no options`);
      }
    }
    addFile(`properties/${safeSeg(t)}.json`, 'properties', t, props, (r) => r.name);
    counts.properties += props.length;
  }
}

// Property groups per object type.
if (raw.propertyGroups) {
  for (const t of Object.keys(raw.propertyGroups).sort()) {
    const groups = (raw.propertyGroups[t] || []).map(scrubCrm).sort(byName);
    addFile(`property-groups/${safeSeg(t)}.json`, 'propertyGroups', t, groups, (r) => r.name);
    counts.propertyGroups += groups.length;
  }
}

// Pipelines and stages per object type.
if (raw.pipelines) {
  for (const t of Object.keys(raw.pipelines).sort()) {
    const pipes = (raw.pipelines[t] || []).map(normPipeline).sort(byOrderThenId);
    for (const p of pipes) {
      const stages = p.stages || [];
      counts.pipelineStages += stages.length;
      if (stages.length === 0) warnings.push(`pipelines/${t}: "${p.label}" has no stages`);
      if (t === 'deals') {
        if (!stages.some((s) => String(s.metadata && s.metadata.isClosed) === 'true')) {
          warnings.push(`pipelines/deals: "${p.label}" has no closed stage (isClosed=true)`);
        }
        for (const s of stages) {
          const pr = Number(s.metadata && s.metadata.probability);
          if (s.metadata && s.metadata.probability !== undefined && (Number.isNaN(pr) || pr < 0 || pr > 1)) {
            warnings.push(`pipelines/deals: stage "${s.label}" probability ${s.metadata.probability} is outside 0-1`);
          }
        }
      }
      const labels = stages.map((s) => s.label);
      const dup = labels.filter((l, i) => labels.indexOf(l) !== i);
      if (dup.length) warnings.push(`pipelines/${t}: "${p.label}" has duplicate stage labels: ${[...new Set(dup)].join(', ')}`);
    }
    addFile(`pipelines/${safeSeg(t)}.json`, 'pipelines', t, pipes, (r) => r.id);
    counts.pipelines += pipes.length;
  }
}

// Workflow metadata (allowlisted fields only).
if (Array.isArray(raw.workflows)) {
  const wfs = raw.workflows.map(normWorkflow).sort((a, b) => cmpIdLike(a.id, b.id));
  addFile('workflows/workflows.json', 'workflows', null, wfs, (r) => r.id);
  counts.workflows = wfs.length;
}

files.sort((a, b) => cmpStr(a.path, b.path));

// ------------------------------------------------------- integrity self-check
const integrity = { checked: 0, passed: 0, failed: [] };
for (const f of files) {
  integrity.checked++;
  let ok = false;
  try {
    const again = serialize(JSON.parse(f.content));
    ok = again === f.content && sha256(again) === f.sha256;
  } catch (e) {
    ok = false;
  }
  if (ok) integrity.passed++;
  else integrity.failed.push(f.path);
}

const sha256sums = files.map((f) => `${f.sha256}  ${f.path}`).join('\n') + (files.length ? '\n' : '');
const bundleSha256 = sha256(sha256sums);
const totalRecords = files.reduce((n, f) => n + f.records, 0);

if (integrity.failed.length) errors.push(`Integrity self-check failed for: ${integrity.failed.join(', ')}`);
if (files.length === 0 || totalRecords === 0) errors.push('Snapshot is empty: no metadata records were exported.');
const endpointErrors = input.endpointErrors || [];

const health = errors.length ? 'FAILED' : endpointErrors.length ? 'DEGRADED' : 'HEALTHY';

const manifest = {
  schemaVersion: '1.0.0',
  generator: 'n8n-hubspot-portal-configuration-snapshot-git-backup',
  portalId: String(config.portalId),
  source: input.source,
  snapshotVersion: config.snapshotVersion,
  capturedAt: config.capturedAt,
  runId: config.runId,
  hashAlgorithm: 'sha256',
  hashEngine,
  bundleSha256,
  health,
  exportScope: scope,
  normalization: opts,
  counts,
  files: Object.fromEntries(files.map((f) => [f.path, {
    kind: f.kind,
    objectType: f.objectType,
    records: f.records,
    bytes: f.bytes,
    sha256: f.sha256,
    recordHashes: f.recordHashes,
  }])),
};

return [{
  json: {
    snapshot: {
      portalId: String(config.portalId),
      root: config.git.snapshotRoot,
      capturedAt: config.capturedAt,
      snapshotVersion: config.snapshotVersion,
      bundleSha256,
      sha256sums,
      totalRecords,
      counts,
      files,
    },
    manifest,
    audit: { health, hashEngine, integrity, warnings, errors, endpointErrors },
  },
}];

// ============================================================================
// Versioned Diff Builder
// Compares the new snapshot with the previous manifest (read from Git in live
// mode, or supplied offline as `previousManifest` by the simulator) at FILE
// and RECORD level, finalises the manifest with lineage, writes the commit
// message, and decides whether the commit gate is open.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const norm = $('Normalization & Checksum Auditor').first().json;
const inp = $input.first().json || {};

// ------------------------------------------------------- previous manifest
let prev = null;
let previousSource = 'none';
if (inp.previousManifest && typeof inp.previousManifest === 'object') {
  prev = inp.previousManifest;
  previousSource = 'offline';
} else if (inp.encoding === 'base64' && typeof inp.content === 'string') {
  try {
    prev = JSON.parse(Buffer.from(inp.content.replace(/\n/g, ''), 'base64').toString('utf8'));
    previousSource = 'git';
  } catch (e) {
    previousSource = 'git-unparseable';
  }
} else if (inp.error) {
  // 404 on the first run is expected; anything else is reported.
  const msg = typeof inp.error === 'string' ? inp.error : inp.error.message || '';
  previousSource = /404|not found/i.test(msg) ? 'git-first-run' : 'git-unavailable';
} else if (config.git.remoteReadAllowed) {
  previousSource = 'git-unavailable';
}

const prevFiles = (prev && prev.files) || {};
const curFiles = Object.fromEntries(norm.snapshot.files.map((f) => [f.path, f]));
const limit = config.limits.maxRecordNamesInCommit;

const added = [];
const modified = [];
const removed = [];
const unchanged = [];

for (const path of Object.keys(curFiles).sort()) {
  const cur = curFiles[path];
  const old = prevFiles[path];
  if (!old) {
    added.push({ path, records: cur.records, sha256: cur.sha256 });
    continue;
  }
  if (old.sha256 === cur.sha256) {
    unchanged.push(path);
    continue;
  }
  const oh = old.recordHashes || {};
  const nh = cur.recordHashes || {};
  const recordsAdded = Object.keys(nh).filter((k) => !(k in oh)).sort();
  const recordsRemoved = Object.keys(oh).filter((k) => !(k in nh)).sort();
  const recordsChanged = Object.keys(nh).filter((k) => k in oh && oh[k] !== nh[k]).sort();
  modified.push({ path, previousSha256: old.sha256, sha256: cur.sha256, recordsAdded, recordsRemoved, recordsChanged });
}
for (const path of Object.keys(prevFiles).sort()) {
  if (!curFiles[path]) removed.push({ path, previousSha256: prevFiles[path].sha256 });
}

const health = norm.audit.health;
// Never prune when the export was degraded: a missing file may only mean a
// failed endpoint, not a deleted configuration.
const pruneEffective = config.git.pruneRemovedFiles && health === 'HEALTHY';
const hasChanges = added.length > 0 || modified.length > 0 || (removed.length > 0 && pruneEffective);

// ------------------------------------------------------------ commit gate
const blockers = [...config.git.staticCommitBlockers];
if (health === 'FAILED') blockers.push('Snapshot health is FAILED');
if (health === 'DEGRADED' && !config.git.commitOnDegraded) blockers.push('Snapshot health is DEGRADED (set GIT_COMMIT_ON_DEGRADED=true to allow)');
if (config.git.remoteReadAllowed && (previousSource === 'git-unavailable' || previousSource === 'git-unparseable')) {
  blockers.push(`Previous manifest could not be read (${previousSource}); refusing to commit a blind diff`);
}
if (!hasChanges) blockers.push('No configuration changes since the previous snapshot');
const commitGate = { allowed: blockers.length === 0, reasons: blockers };

// --------------------------------------------------------- final manifest
const manifest = {
  ...norm.manifest,
  lineage: {
    previousSnapshotVersion: prev ? prev.snapshotVersion || null : null,
    previousBundleSha256: prev ? prev.bundleSha256 || null : null,
    previousSource,
  },
  changeSummary: {
    added: added.map((a) => a.path),
    modified: modified.map((m) => m.path),
    removed: removed.map((r) => r.path),
    pruned: pruneEffective ? removed.map((r) => r.path) : [],
  },
};
const canonical = (v) => {
  if (Array.isArray(v)) return v.map(canonical);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v).sort()) if (v[k] !== undefined) o[k] = canonical(v[k]);
    return o;
  }
  return v;
};
const manifestContent = JSON.stringify(canonical(manifest), null, 2) + '\n';

// ---------------------------------------------------------- commit message
const fmtList = (arr) => {
  if (!arr.length) return '';
  const shown = arr.slice(0, limit).join(', ');
  return arr.length > limit ? `${shown}, ... (+${arr.length - limit} more)` : shown;
};
const lines = [];
lines.push(
  `chore(snapshot): portal-${config.portalId} ${config.snapshotVersion} [+${added.length} ~${modified.length} -${pruneEffective ? removed.length : 0}]`
);
lines.push('');
lines.push(`Bundle:   sha256:${norm.snapshot.bundleSha256}`);
lines.push(`Previous: ${manifest.lineage.previousBundleSha256 ? 'sha256:' + manifest.lineage.previousBundleSha256 : 'none (' + previousSource + ')'}`);
lines.push(`Health:   ${health} | records: ${norm.snapshot.totalRecords} | hash engine: ${norm.audit.hashEngine}`);
lines.push(`Run:      ${config.runId} (${norm.manifest.source})`);
lines.push('');
if (added.length || modified.length || removed.length) lines.push('Changes:');
for (const a of added) lines.push(`+ ${a.path} (${a.records} records)`);
for (const m of modified) {
  const parts = [];
  if (m.recordsAdded.length) parts.push(`added: ${fmtList(m.recordsAdded)}`);
  if (m.recordsChanged.length) parts.push(`changed: ${fmtList(m.recordsChanged)}`);
  if (m.recordsRemoved.length) parts.push(`removed: ${fmtList(m.recordsRemoved)}`);
  lines.push(`~ ${m.path}${parts.length ? ' | ' + parts.join(' | ') : ''}`);
}
for (const r of removed) lines.push(`${pruneEffective ? '-' : '!'} ${r.path}${pruneEffective ? '' : ' (missing from export; kept in repo, pruning disabled)'}`);
if (norm.audit.warnings.length) {
  lines.push('');
  lines.push(`Warnings (${norm.audit.warnings.length}):`);
  for (const w of norm.audit.warnings.slice(0, 10)) lines.push(`- ${w}`);
}
const commitMessage = lines.join('\n') + '\n';

return [{
  json: {
    diff: {
      previousSource,
      hasChanges,
      pruneEffective,
      added,
      modified,
      removed,
      unchangedCount: unchanged.length,
    },
    commitGate,
    commitMessage,
    manifestPath: `${config.git.snapshotRoot}/manifest.json`,
    manifestContent,
    sha256sumsPath: `${config.git.snapshotRoot}/SHA256SUMS`,
  },
}];

// ============================================================================
// Build Git Tree Payload  (only reached when the commit gate is OPEN)
// Input: the branch head commit returned by "Git: Get Head Commit".
// Builds a single atomic Git Data API tree: every changed snapshot file plus
// manifest.json and SHA256SUMS. Deletions are emitted only when pruning is
// effective (GIT_PRUNE_REMOVED_FILES=true and snapshot health HEALTHY).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const norm = $('Normalization & Checksum Auditor').first().json;
const d = $('Versioned Diff Builder').first().json;
const head = $input.first().json;

const headSha = head && head.sha;
const baseTree = head && head.tree && head.tree.sha;
if (!/^[0-9a-f]{40}$/i.test(String(headSha)) || !/^[0-9a-f]{40}$/i.test(String(baseTree))) {
  throw new Error('Could not read the branch head commit/tree SHA from GitHub; aborting before any write.');
}
if (!d.commitGate.allowed) {
  throw new Error('Commit gate is closed; this node must not run. Reasons: ' + d.commitGate.reasons.join('; '));
}

const root = config.git.snapshotRoot;
const changed = new Set([...d.diff.added.map((a) => a.path), ...d.diff.modified.map((m) => m.path)]);
const tree = [];
for (const f of norm.snapshot.files) {
  if (!changed.has(f.path)) continue;
  tree.push({ path: `${root}/${f.path}`, mode: '100644', type: 'blob', content: f.content });
}
if (d.diff.pruneEffective) {
  for (const r of d.diff.removed) tree.push({ path: `${root}/${r.path}`, mode: '100644', type: 'blob', sha: null });
}
tree.push({ path: d.manifestPath, mode: '100644', type: 'blob', content: d.manifestContent });
tree.push({ path: d.sha256sumsPath, mode: '100644', type: 'blob', content: norm.snapshot.sha256sums });

return [{
  json: {
    parentCommitSha: headSha,
    treeRequest: { base_tree: baseTree, tree },
    commitRequestBase: {
      message: d.commitMessage,
      parents: [headSha],
      author: { name: config.git.commitAuthorName, email: config.git.commitAuthorEmail, date: config.capturedAt },
    },
    entryCount: tree.length,
  },
}];

// ============================================================================
// Commit Result
// Input: the updated ref returned by "Git: Update Branch Ref".
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const ref = $input.first().json;
const created = $('Git: Create Commit').first().json;
const commitSha = (ref && ref.object && ref.object.sha) || created.sha;
if (commitSha !== created.sha) {
  throw new Error(`Branch ref points at ${commitSha} but the created commit is ${created.sha}; verify the branch manually.`);
}
return [{
  json: {
    mode: 'committed',
    commit: {
      sha: commitSha,
      branch: config.git.branch,
      url: config.git.webUrl ? `${config.git.webUrl}/commit/${commitSha}` : (created.html_url || null),
      entries: $('Build Git Tree Payload').first().json.entryCount,
    },
  },
}];

// ============================================================================
// Dry-Run Preview
// Shows exactly what WOULD be written to Git, and why it was not. Performs no
// network calls. File contents stay available on the Normalization node's
// output for inspection inside the n8n execution view.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const norm = $('Normalization & Checksum Auditor').first().json;
const d = $input.first().json;
const root = config.git.snapshotRoot;
const changed = new Set([...d.diff.added.map((a) => a.path), ...d.diff.modified.map((m) => m.path)]);

const treeEntries = norm.snapshot.files
  .filter((f) => changed.has(f.path))
  .map((f) => ({ action: d.diff.added.some((a) => a.path === f.path) ? 'add' : 'modify', path: `${root}/${f.path}`, bytes: f.bytes, sha256: f.sha256 }));
if (d.diff.pruneEffective) for (const r of d.diff.removed) treeEntries.push({ action: 'delete', path: `${root}/${r.path}` });
if (d.diff.hasChanges) {
  treeEntries.push({ action: 'write', path: d.manifestPath, bytes: d.manifestContent.length });
  treeEntries.push({ action: 'write', path: d.sha256sumsPath, bytes: norm.snapshot.sha256sums.length });
}

return [{
  json: {
    mode: 'dry-run',
    wouldCommit: d.diff.hasChanges,
    blockedBy: d.commitGate.reasons,
    preview: {
      repository: config.git.repo || '(GITHUB_REPOSITORY not set)',
      branch: config.git.branch,
      commitMessage: d.commitMessage,
      treeEntries,
    },
  },
}];

// ============================================================================
// RevOps Summary Builder
// Builds a compact health report plus a Slack-compatible payload
// ({ text, blocks }) that also works with most generic JSON webhooks.
// Never includes tokens, file contents or record values.
// ============================================================================
const { config, safetyDecisions } = $('Config & Safety Gate').first().json;
const norm = $('Normalization & Checksum Auditor').first().json;
const d = $('Versioned Diff Builder').first().json;
const r = $input.first().json;

const health = norm.audit.health;
const status =
  health === 'FAILED' ? 'FAILED'
  : r.mode === 'committed' ? 'COMMITTED'
  : d.diff.hasChanges ? 'CHANGES_PENDING'
  : 'NO_CHANGES';
const icon = health === 'HEALTHY' ? ':large_green_circle:' : health === 'DEGRADED' ? ':large_yellow_circle:' : ':red_circle:';
const c = norm.snapshot.counts;
const modeLabel = config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'LIVE / DRY-RUN' : 'LIVE';

const summary = {
  status,
  health,
  mode: modeLabel,
  portalId: config.portalId,
  snapshotVersion: config.snapshotVersion,
  runId: config.runId,
  bundleSha256: norm.snapshot.bundleSha256,
  integrity: { checked: norm.audit.integrity.checked, passed: norm.audit.integrity.passed, failed: norm.audit.integrity.failed },
  hashEngine: norm.audit.hashEngine,
  counts: c,
  totalRecords: norm.snapshot.totalRecords,
  files: norm.snapshot.files.length,
  changes: {
    added: d.diff.added.length,
    modified: d.diff.modified.length,
    removed: d.diff.removed.length,
    pruned: d.diff.pruneEffective ? d.diff.removed.length : 0,
    previousSource: d.diff.previousSource,
  },
  commit: r.mode === 'committed' ? r.commit : null,
  blockedBy: r.mode === 'committed' ? [] : d.commitGate.reasons,
  warnings: norm.audit.warnings,
  errors: norm.audit.errors,
  endpointErrors: norm.audit.endpointErrors,
  safetyDecisions,
};

const changeLine = `+${summary.changes.added} added · ~${summary.changes.modified} modified · -${summary.changes.removed} missing`;
const commitLine = summary.commit
  ? `Committed \`${summary.commit.sha.slice(0, 12)}\` to \`${summary.commit.branch}\`${summary.commit.url ? ` (<${summary.commit.url}|view>)` : ''}`
  : `No commit: ${summary.blockedBy.slice(0, 3).join('; ') || 'n/a'}`;

const text = `${icon} HubSpot config snapshot ${summary.status} · portal ${summary.portalId} · ${summary.snapshotVersion} · ${modeLabel}`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `HubSpot Config Snapshot: ${summary.status}`, emoji: true } },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Health*\n${icon} ${health}` },
      { type: 'mrkdwn', text: `*Mode*\n${modeLabel}` },
      { type: 'mrkdwn', text: `*Portal*\n${summary.portalId}` },
      { type: 'mrkdwn', text: `*Version*\n${summary.snapshotVersion}` },
      { type: 'mrkdwn', text: `*Objects*\n${c.customObjects} custom objects · ${c.properties} properties · ${c.propertyGroups} groups` },
      { type: 'mrkdwn', text: `*Pipelines / Workflows*\n${c.pipelines} pipelines (${c.pipelineStages} stages) · ${c.workflows} workflows` },
    ],
  },
  { type: 'section', text: { type: 'mrkdwn', text: `*Changes*: ${changeLine}\n*Git*: ${commitLine}` } },
  {
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `Integrity ${summary.integrity.passed}/${summary.integrity.checked} files verified · bundle sha256:${summary.bundleSha256.slice(0, 16)}… · ${summary.warnings.length} warnings · ${summary.endpointErrors.length} endpoint errors`,
    }],
  },
];
if (summary.endpointErrors.length || summary.errors.length) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Issues*\n' + [...summary.errors, ...summary.endpointErrors.map((e) => `${e.key}: ${e.message}`)].slice(0, 8).map((x) => `• ${x}`).join('\n'),
    },
  });
}

return [{ json: { summary, slackPayload: { text, blocks } } }];

// ============================================================================
// Run Log (No External Calls)
// Terminal node when notifications are disabled. The summary is visible in the
// n8n execution log; nothing leaves the n8n instance.
// ============================================================================
const { summary } = $input.first().json;
return [{ json: { logged: true, notification: 'skipped (NOTIFICATIONS_ENABLED is not true or SLACK_WEBHOOK_URL is unset)', summary } }];
